function plot_pinn_spme_generated_profiles(dataset_dir, save_figures)
%PLOT_PINN_SPME_GENERATED_PROFILES Plot current and voltage from generated PINN-SPMe datasets.
%
% Usage:
%   plot_pinn_spme_generated_profiles
%   plot_pinn_spme_generated_profiles('results/PINN_SPMe_dataset')
%   plot_pinn_spme_generated_profiles('results/PINN_SPMe_dataset', true)
%
% Expected input files:
%   *.csv generated by generate_pinn_spme_training_data_LGM50.m
%
% Required CSV columns:
%   time_s, current_A, voltage_V
%
% Output:
%   One overview figure containing all profiles.
%   Optional PNG/PDF files saved to:
%       <dataset_dir>/plots/

if nargin < 1 || isempty(dataset_dir)
    dataset_dir = fullfile(pwd, 'results', 'PINN_SPMe_dataset');
end
if nargin < 2
    save_figures = true;
end

if ~isfolder(dataset_dir)
    error('Dataset folder not found: %s', dataset_dir);
end

files = dir(fullfile(dataset_dir, '*.csv'));
files = files(~strcmp({files.name}, 'dataset_summary.csv'));

if isempty(files)
    error('No dataset CSV files found in: %s', dataset_dir);
end

plot_dir = fullfile(dataset_dir, 'plots');
if save_figures && ~isfolder(plot_dir)
    mkdir(plot_dir);
end

fprintf('Found %d dataset CSV files in:\n  %s\n', numel(files), dataset_dir);

% -------------------------------------------------------------------------
% Overview figure: one row per profile, current and voltage columns.
% -------------------------------------------------------------------------
n = numel(files);
fig = figure('Name', 'PINN-SPMe generated profiles', ...
             'Color', 'w', ...
             'Units', 'pixels', ...
             'Position', [100, 100, 1200, max(320, 260*n)]);

tl = tiledlayout(n, 2, 'TileSpacing', 'compact', 'Padding', 'compact');
title(tl, 'PINN-SPMe generated datasets: current and voltage');

summary = table('Size', [n 8], ...
    'VariableTypes', {'string','double','double','double','double','double','double','double'}, ...
    'VariableNames', {'profile','n_samples','duration_s','min_current_A','max_current_A', ...
                      'initial_voltage_V','final_voltage_V','min_voltage_V'});

for k = 1:n
    file_path = fullfile(files(k).folder, files(k).name);
    T = readtable(file_path);

    require_columns(T, {'time_s','current_A','voltage_V'}, file_path);

    t = T.time_s;
    I = T.current_A;
    V = T.voltage_V;

    [~, profile_name] = fileparts(files(k).name);
    profile_label = strrep(profile_name, '_', '\_');

    summary.profile(k) = string(profile_name);
    summary.n_samples(k) = numel(t);
    summary.duration_s(k) = t(end) - t(1);
    summary.min_current_A(k) = min(I);
    summary.max_current_A(k) = max(I);
    summary.initial_voltage_V(k) = V(1);
    summary.final_voltage_V(k) = V(end);
    summary.min_voltage_V(k) = min(V);

    % Current plot
    nexttile;
    plot(t, I, 'LineWidth', 1.0);
    grid on;
    ylabel('Current [A]');
    title(sprintf('%s current', profile_label));
    if k == n
        xlabel('Time [s]');
    end

    % Voltage plot
    nexttile;
    plot(t, V, 'LineWidth', 1.0);
    grid on;
    ylabel('Voltage [V]');
    title(sprintf('%s voltage', profile_label));
    if k == n
        xlabel('Time [s]');
    end

    % Individual figure for each profile
    fig_one = figure('Name', profile_name, 'Color', 'w', ...
                     'Units', 'pixels', 'Position', [100, 100, 1000, 520]);
    tl_one = tiledlayout(2, 1, 'TileSpacing', 'compact', 'Padding', 'compact');
    title(tl_one, sprintf('%s: current and voltage', profile_label));

    nexttile;
    plot(t, I, 'LineWidth', 1.0);
    grid on;
    ylabel('Current [A]');

    nexttile;
    plot(t, V, 'LineWidth', 1.0);
    grid on;
    ylabel('Voltage [V]');
    xlabel('Time [s]');

    if save_figures
        exportgraphics(fig_one, fullfile(plot_dir, profile_name + "_current_voltage.png"), 'Resolution', 200);
        exportgraphics(fig_one, fullfile(plot_dir, profile_name + "_current_voltage.pdf"));
        close(fig_one);
    end
end

if save_figures
    exportgraphics(fig, fullfile(plot_dir, 'all_profiles_current_voltage.png'), 'Resolution', 200);
    exportgraphics(fig, fullfile(plot_dir, 'all_profiles_current_voltage.pdf'));
    writetable(summary, fullfile(plot_dir, 'profile_plot_summary.csv'));
    fprintf('Saved plots to:\n  %s\n', plot_dir);
end

disp(summary);

end

function require_columns(T, required, file_path)
    names = T.Properties.VariableNames;
    missing = setdiff(required, names);
    if ~isempty(missing)
        error('File %s is missing required columns: %s', file_path, strjoin(missing, ', '));
    end
end
